<?php error_reporting(0);if(!isset($_SESSION['mikhmon'])){header('Location:../admin.php?id=login');exit;}$rows=$API->comm('/ppp/profile/print');function ppp_h($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
?><div class="row"><div class="col-12"><div class="card"><div class="card-header"><h3><i class="fa fa-list"></i> Profils PPP &nbsp;|&nbsp; <a href="./?ppp=add-profile&session=<?=ppp_h($session);?>"><i class="fa fa-plus"></i> Ajouter</a></h3></div><div class="card-body"><div class="overflow box-bordered"><table id="dataTable" class="table table-bordered table-hover"><thead><tr><th>Actions</th><th>Nom</th><th>Adresse locale</th><th>Pool distant</th><th>Limite débit</th><th>Un seul</th></tr></thead><tbody><?php foreach($rows as $r){echo '<tr><td><a href="./?ppp=edit-profile&profile='.urlencode($r['.id']).'&session='.ppp_h($session).'"><i class="fa fa-edit"></i></a> <a class="text-danger" onclick="return confirm(\'Supprimer ce profil ?\')" href="./?remove-pprofile='.urlencode($r['.id']).'&session='.ppp_h($session).'"><i class="fa fa-trash"></i></a></td><td>'.ppp_h($r['name']).'</td><td>'.ppp_h(isset($r['local-address'])?$r['local-address']:'').'</td><td>'.ppp_h(isset($r['remote-address'])?$r['remote-address']:'').'</td><td>'.ppp_h(isset($r['rate-limit'])?$r['rate-limit']:'').'</td><td>'.ppp_h(isset($r['only-one'])?$r['only-one']:'').'</td></tr>';}?></tbody></table></div></div></div></div></div>
